"""heatfin_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 0 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python heatfin_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = -80.0    # level along z
z1 = 0.0    # level along z

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z -80.0 to 0.0 ------------------------------
count_1 = 11                  # the period repeats 11 times, each moved by step_1
step_1 = Vector(*P(-5.144467, 0.0))
period_1 = [
    cf.segment(P(28.79457, 35.0), P(27.79457, 35.0)),
    cf.segment(P(27.79457, 35.0), P(26.22233, 5.0)),
    cf.segment(P(26.22233, 5.0), P(25.22233, 5.0)),
    cf.segment(P(25.22233, 5.0), P(23.650103, 35.0)),
]
rest_1 = [                     # the outline after the last copy, back to the start
    cf.segment(P(-27.794567, 35.0), P(-28.794567, 35.0)),
    cf.segment(P(-28.794567, 35.0), P(-30.62884, 0.0)),
    cf.segment(P(-30.62884, 0.0), P(30.62884, 0.0)),
    cf.segment(P(30.62884, 0.0), P(28.79457, 35.0)),
]
outline_1 = cf.wire(*[e.translate(step_1 * m) for m in range(count_1) for e in period_1], *rest_1)
part = prism(outline_1, z0, z1)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "heatfin_exact.step")
